window.importarSacolinhas = async () => {
  const porNumero = new Map(sacolinhas.map(s => [Number(s.numero), s]));
  const novos = [], atualizar = [];

  DADOS.forEach(d => {
    const atual = porNumero.get(d.n);
    if (!atual) { novos.push(d); return; }

    // Preenche apenas o que está vazio ou desatualizado no sistema
    const p = partesComunidade(atual);
    const mudancas = {};
    if (p.com   !== d.c)  mudancas.comunidade = d.c;
    if (p.lider !== d.l)  mudancas.lider      = d.l;
    if (d.s  && !atual.sexo)    mudancas.sexo    = d.s;
    if (d.i  && !atual.idade)   mudancas.idade   = d.i;
    if (d.r  && !atual.roupa)   mudancas.roupa   = d.r;
    if (d.ca && !atual.calcado) mudancas.calcado = d.ca;
    if (d.ne && (!atual.necesp || atual.necesp === 'Não')) mudancas.necesp = d.ne;
    if (Object.keys(mudancas).length) atualizar.push({ id: atual.id, mudancas });
  });

  if (!novos.length && !atualizar.length) {
    toast('✅ Tudo em dia! Os ' + DADOS.length + ' cadastros já estão completos.');
    return;
  }

  const partes = [];
  if (novos.length)     partes.push('cadastrar ' + novos.length + ' crianças');
  if (atualizar.length) partes.push('completar os dados de ' + atualizar.length + ' cadastros');
  const ok = await confirmar('Deseja ' + partes.join(' e ') + '?');
  if (!ok) return;

  toast('⏳ Processando… aguarde, não feche a página.', 6000);

  try {
    for (let i = 0; i < atualizar.length; i += 400) {
      const lote = atualizar.slice(i, i + 400);
      const batch = writeBatch(db);
      lote.forEach(u => batch.update(doc(db, 'sacolinhas', u.id), u.mudancas));
      await batch.commit();
      toast('⏳ ' + Math.min(i + 400, atualizar.length) + ' de ' + atualizar.length + ' atualizados…', 4000);
    }

    for (let i = 0; i < novos.length; i += 400) {
      const lote = novos.slice(i, i + 400);
      const batch = writeBatch(db);
      lote.forEach(d => {
        batch.set(doc(collection(db, 'sacolinhas')), {
          numero: d.n, comunidade: d.c, lider: d.l, nome: d.no,
          sexo: d.s, idade: d.i, roupa: d.r, calcado: d.ca,
          necesp: d.ne || 'Não', entrega: '',
          status: 'aguardando', criadoEm: serverTimestamp()
        });
      });
      await batch.commit();
      toast('⏳ ' + Math.min(i + 400, novos.length) + ' de ' + novos.length + ' cadastradas…', 4000);
    }

    const msgs = [];
    if (novos.length)     msgs.push(novos.length + ' cadastradas');
    if (atualizar.length) msgs.push(atualizar.length + ' atualizadas');
    toast('🎉 Concluído! ' + msgs.join(' e ') + '.', 6000);
  } catch (e) {
    console.error(e);
    toast('❌ Erro no processamento. Verifique a conexão e tente novamente.', 6000);
  }
};
